from collections import Counter
from typing import Dict, Any

def histogram(test: str) -> Dict[str, int]:
    """
    Given a string representing a space-separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # 1. Handle empty input
    if not test:
        return {}

    # 2. Split the string by spaces and count occurrences
    # Counter is efficient O(n) for this operation
    counts = Counter(test.split())

    # 3. Find the maximum count
    max_count = max(counts.values())

    # 4. Return all letters that have the maximum count
    return {char: count for char, count in counts.items() if count == max_count}
