"""
Module: utils/helpers.py
Purpose: Utility functions for string validation and processing.
"""

def check_if_last_char_is_a_letter(txt: str) -> bool:
    """
    Create a function that returns True if the last character
    of a given string is an alphabetical character and is not
    a part of a word, and False otherwise.

    Note: "word" is defined as a group of characters separated by space.

    Args:
        txt (str): The input string to analyze.

    Returns:
        bool: True if the last character is a standalone letter, False otherwise.
    """
    if not txt:
        return False

    # Get the last character of the string
    last_char = txt[-1]

    # Check if the last character is an alphabetical character
    # isalpha() returns True for letters (a-z, A-Z) and False for punctuation, numbers, spaces, etc.
    if not last_char.isalpha():
        return False

    # Check if the last character is NOT part of a word
    # A character is part of a word if it is preceded by a space or the string starts with it.

    # Edge Case: If the string has only one character, it cannot be part of a word.
    # So, if len(txt) == 1, it is not part of a word.
    if len(txt) == 1:
        return True

    # Check if the character before the last one is a space
    # We use a simple index check. If txt[-2] == ' ', then it's part of a word.
    # Note: We must ensure txt[-2] exists before accessing it.
    if len(txt) > 1 and txt[-2] == ' ':
        return False

    return True
```

