def encode(message):
    """
    Encodes a message by swapping case and replacing vowels with letters 2 places ahead.
    Note: This implementation handles both lowercase and uppercase vowels correctly.
    """
    vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}
    result = []

    for char in message:
        if char in vowels:
            # Replace vowel with letter 2 places ahead
            # We handle lowercase and uppercase separately to ensure correct mapping
            if char.islower():
                result.append(chr(ord(char) + 2))
            else:
                result.append(chr(ord(char) + 2))
        elif char.isalpha():
            # Swap case
            result.append(char.swapcase())
        else:
            # Keep non-alphabetic characters as is
            result.append(char)

    return "".join(result)
