    vowel_map = {
        'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 'w',
        'A': 'C', 'E': 'G', 'I': 'K', 'O': 'Q', 'U': 'W'
    }

    result = []
    for char in message:
        if char.lower() in ['a', 'e', 'i', 'o', 'u']:
            if char.isupper():
                result.append(vowel_map[char].lower())
            else:
                result.append(vowel_map[char].upper())
        else:
            result.append(char.swapcase())

