def skjkasdkd(lst):
    """
    Finds the largest prime in the list and returns the sum of its digits.
    Returns 0 if no prime is found.
    """

    def is_prime(n):
        """Check if a number is prime."""
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    def digit_sum(num):
        """Calculate the sum of digits of a positive integer."""
        return sum(int(d) for d in str(num))

    # Filter primes
    primes = [num for num in lst if is_prime(num)]

    # Handle case where no primes exist
    if not primes:
        return 0

    # Find largest prime and calculate digit sum
    largest_prime = max(primes)
    return digit_sum(largest_prime)
