    integer palindromes that fall within the range(1, n), inclusive.
    """
    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        s_i = str(i)
        # Check if palindrome by comparing string to reversed string
        if s_i == s_i[::-1]:
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

