def minPath(grid, k):
    """
    Finds the lexicographically smallest path of length k in the grid.
    """
    if k == 1:
        return [1]

    n = len(grid)

    def get_sorted_neighbors(r, c):
        neighbors = []
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                neighbors.append((grid[nr][nc], nr, nc))

        neighbors.sort(key=lambda x: x[0])
        return neighbors

    def dfs(path, r, c, steps_left):
        if steps_left == 0:
            return path

        neighbors = get_sorted_neighbors(r, c)

        for val, nr, nc in neighbors:
            new_path = path + [val]
            result = dfs(new_path, nr, nc, steps_left - 1)

            if result is not None:
                return result

        return None

    start_r, start_c = -1, -1
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 1:
                start_r, start_c = r, c
                break
        if start_r != -1:
            break

    return dfs([1], start_r, start_c, k - 1)
