    return "".join(result)

def correct_bracketing(brackets: str):
    """
    brackets is a string of "<" and ">".
    return True if every opening bracket has a corresponding closing bracket.
    """
    stack = []
    for char in brackets:
        if char == "<":
            stack.append(">")
        elif char == ">":
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def monotonic(l: list):
    """Return True is list elements are monotonically increasing or decreasing.
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if not l:
        return True

    # Check if all elements are strictly increasing
    for i in range(1, len(l)):
        if l[i] < l[i - 1]:
            return False

    # Check if all elements are strictly decreasing
    for i in range(1, len(l)):
        if l[i] > l[i - 1]:
            return False

    return True

def correct_bracketing(brackets: str):
