        return False

    # Check if the month is valid based on the number of days
    if month == 2:
        # February has 29 days in a leap year
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            if day < 29:
                return False
    else:
        # For other months, February has 29 days
        if month == 4:
            if day < 30:
                return False
        elif month == 6:
            if day < 31:
                return False
        elif month == 9:
            if day < 30:
                return False
        elif month == 11:
            if day < 30:
                return False

    # Check if the date is in the correct format: mm-dd-yyyy
    if not (str(month) == str(day) and str(day) == str(year)):
        return False

    return True
