from typing import Callable

class float:
    def __init__(self, s):
        self._val = float(s)

    def __eq__(self, other):
        return self._val == other._val

    def __lt__(self, other):
        return self._val < other._val

    def __gt__(self, other):
        return self._val > other._val

    def __le__(self, other):
        return self._val <= other._val

    def __ge__(self, other):
        return self._val >= other._val

    def __hash__(self):
        return hash(self._val)

    def __repr__(self):
        return f"float({self._val})"

class set:
    def __init__(self, s):
        self._set = set(s)

    def __eq__(self, other):
        return self._set == other._set

    def __hash__(self):
        return hash(self._set)

    def __repr__(self):
        return f"set({self._set})"

class Callable:
    def __init__(self, func):
        self._func = func

    def __call__(self, *args, **kwargs):
        return self._func(*args, **kwargs)

    def __name__(self):
        return self._func.__name__

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    # Convert inputs to a comparable type (float)
    # This handles integers, floats, and strings by converting them to float
    # and comparing them.
    # If the string is a valid float representation (e.g., "2,3" -> 2.3),
    # we compare the float values. If the string is not a valid float,
    # we treat it as a string and compare the string values directly.
    try:
        # Convert to float to handle various numeric representations
        a = float(a)
        b = float(b)
    except (ValueError, TypeError):
        # If conversion fails, treat as strings and compare directly
        a = a
        b = b

    # Compare the two values
    if a > b:
        return a
    elif b > a:
        return b
    else:
        return None
