def histogram(test):
    """
    Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    # Handle empty or whitespace-only input immediately
    if not test or not test.strip():
        return {}

    # Split the string by whitespace to get individual characters
    # This handles multiple spaces and leading/trailing whitespace gracefully
    chars = test.split()

    if not chars:
        return {}

    # Count frequencies using a standard dictionary
    counts = {}
    for char in chars:
        counts[char] = counts.get(char, 0) + 1

    # Determine the maximum frequency
    max_count = max(counts.values())

    # Filter the dictionary to include only characters with the maximum frequency
    return {char: count for char, count in counts.items() if count == max_count}
